// Optional player records use the existing save key so previous progress stays intact.
state.records=state.records&&typeof state.records==='object'?state.records:{};
state.friends=state.friends&&typeof state.friends==='object'?state.friends:{};
state.challenges=Array.isArray(state.challenges)?state.challenges:[];
const friendCatalog=[
{id:'nod',rarity:'N',name:'點頭之交',icon:'🙂',desc:'見面點點頭，已經完成今天的社交暖身。'},
{id:'bus',rarity:'N',name:'同一班公車的人',icon:'🚌',desc:'每天同一站出現，熟悉的陌生人也算一種陪伴。'},
{id:'smile',rarity:'N',name:'見面會微笑的人',icon:'😊',desc:'不一定有很多話，但會記得對你笑一下。'},
{id:'story',rarity:'SR',name:'會回限動的人',icon:'📱',desc:'你的晚餐照片，終於有一個認真看過的人。'},
{id:'snack',rarity:'SR',name:'陪你吃宵夜的人',icon:'🍜',desc:'一句「餓了」，就能約到一碗熱湯。'},
{id:'invite',rarity:'SSR',name:'主動約你的人',icon:'🎟️',desc:'不用每次你先開口，他也會問：週末有空嗎？'},
{id:'dream',rarity:'SSR',name:'一起完成夢想的朋友',icon:'🌟',desc:'會聽你的新點子，也願意一起把它做出來。'}];
const npcProfiles=[{name:'阿電',icon:'🤖',style:'省牌派',desc:'先出小牌，盡量保留可組成對子的牌。',pass:'先省著，下一手再來。',win:'牌數歸零，系統正常。',lose:'下次更新演算法。'},
{name:'小花',icon:'😎',style:'搶先派',desc:'對手牌少時會搶大牌；色牌偏愛功能牌。',pass:'這手先讓你，我在等大招。',win:'搶先一步，收工！',lose:'好啦，這局你比較快。'},
{name:'老王',icon:'🧋',style:'組牌派',desc:'領出偏愛多張組合；色牌會留意手上最多的顏色。',pass:'喝口茶，看看下一輪。',win:'牌整理好了，人也可以休息了。',lose:'不急，下一桌再見。'}];
const npcName=i=>i===0?'你':npcProfiles[i-1].name;
function npcRemark(i,event){if(i===0)return '你：下一局也請多指教！';let p=npcProfiles[i-1];return p.name+'：'+(state.gentle&&event==='lose'?'這局很精彩，再來一局吧。':p[event])}
let challengeNotice="";
function recordRound(game,detail={}){if(!games.some(g=>g[0]===game))return;let r=state.records[game]||(state.records[game]={played:0,wins:0,losses:0,draws:0,left:0,right:0,streak:0,bestStreak:0,bestScore:0,lastScore:0,modes:{}});r.played++;let outcome=detail.outcome||'complete';if(outcome==='win')r.wins++;if(outcome==='lose')r.losses++;if(outcome==='draw')r.draws++;if(detail.side)r[detail.side]++;r.streak=outcome==='win'?r.streak+1:0;r.bestStreak=Math.max(r.bestStreak,r.streak);if(Number.isFinite(detail.score)){r.lastScore=detail.score;r.bestScore=Math.max(r.bestScore,detail.score)}if(detail.tries)r.bestTries=r.bestTries?Math.min(r.bestTries,detail.tries):detail.tries;if(detail.mode){let m=r.modes[detail.mode]||(r.modes[detail.mode]={played:0,wins:0,losses:0,draws:0});m.played++;if(outcome==='win')m.wins++;if(outcome==='lose')m.losses++;if(outcome==='draw')m.draws++}state.lastRound={game,outcome,side:detail.side||'',score:detail.score??null};updateChallenges(game,detail,r)}
function addFriend(rarity,name){let f=friendCatalog.find(f=>f.rarity===rarity&&f.name===name);if(!f)return;state.friends[f.id]=(state.friends[f.id]||0)+1}
function updateChallenges(game,detail,r){let awards=[];for(let c of state.challenges){if(c.done||c.game!==game)continue;let add=0;if(c.metric==='played')add=1;if(c.metric==='wins'&&detail.outcome==='win')add=1;if(c.metric==='left'&&detail.side==='left')add=1;if(c.metric==='right'&&detail.side==='right')add=1;if(c.metric==='ssr')add=detail.ssr||0;if(c.metric==='score')c.progress=Math.max(c.progress,detail.score||0);else if(c.metric==='streak')c.progress=detail.outcome==='win'?c.progress+1:0;else c.progress+=add;if(c.progress>=c.target){c.done=true;c.completedAt=new Date().toISOString();state.points+=30;awards.push(c.name)}}if(awards.length)challengeNotice='🎯 挑戰達成：'+awards.join('、')+' · 每項 +30 點'}
const percent=(n,total)=>total?Math.round(n/total*100)+'%':'—';
function recordSummary(id,r){if(!r)return '還沒有新戰績';if(id==='rps')return `左手 ${r.left} 勝 · 右手 ${r.right} 勝 · 平手 ${r.draws}｜左 ${percent(r.left,r.played)}／右 ${percent(r.right,r.played)}`;if(id==='dino')return '最高 '+Math.max(state.best,r.bestScore)+' 分 · 最近 '+r.lastScore+' 分';if(id==='2048')return '最高合併分數 '+r.bestScore+' · 通關 '+r.wins+' 次';if(id==='number')return '最快 '+(r.bestTries||'—')+' 次猜中';if(id==='summon')return '收藏 '+friendCatalog.filter(f=>state.friends[f.id]).length+'／7 種朋友';if(r.wins+r.losses+r.draws)return `${r.wins} 勝／${r.losses} 敗／${r.draws} 平 · 勝率 ${percent(r.wins,r.played)} · 最長 ${r.bestStreak} 連勝`;return '完成 '+r.played+' 次'}
function openPanel(title,tag){stop();active='';$('#gameTitle').textContent=title;$('#gameTag').textContent=tag;$('#modal').showModal()}
function openRecords(){openPanel('遊戲戰績','PLAYER RECORDS');ui('<p>詳細戰績從本次更新起記錄；以前的等級、總局數與恐龍最高分仍保留。勝率以全部已完成局數計算，包含平手。左右手數據是出拳結果統計。</p><div class="record-list">'+games.map(g=>{let r=state.records[g[0]];return `<section class="record-entry"><h3>${g[1]} ${g[2]} <small>${r?.played||0} 局</small></h3><p>${recordSummary(g[0],r)}</p>${r?.modes?Object.entries(r.modes).map(([name,m])=>`<div class="mode-record">${name}：${m.wins} 勝／${m.losses} 敗／${m.draws} 平 · ${percent(m.wins,m.played)}</div>`).join(''):''}<button class="quiet" data-play="${g[0]}">去玩</button></section>`}).join('')+'</div>');$('#game').querySelectorAll('[data-play]').forEach(b=>b.onclick=()=>openGame(b.dataset.play))}
function openFriends(){openPanel('朋友圖鑑','FRIEND COLLECTION');let owned=friendCatalog.filter(f=>state.friends[f.id]).length;ui(`<p>已收藏 ${owned}／${friendCatalog.length} 種 · 更新前只記得抽卡總次數，無法回推舊卡；新的朋友會自動收藏。</p><div class="friend-grid">${friendCatalog.map(f=>{let n=state.friends[f.id]||0;return `<article class="friend-entry rarity-${f.rarity} ${n?'':'undiscovered'}"><span class="friend-icon">${n?f.icon:'？'}</span><small>${f.rarity}</small><h3>${f.name}</h3><p>${n?f.desc:'尚未遇見，去朋友召喚池碰碰運氣。'}</p><strong>${n?'已抽到 '+n+' 次':'未收藏'}</strong></article>`}).join('')}</div><div class="choices"><button class="primary" id="toSummon">去抽朋友</button></div>`);$('#toSummon').onclick=()=>openGame('summon')}
const metricsFor=id=>id==='rps'?[['left','左手勝場'],['right','右手勝場'],['streak','左手連勝'],['played','完成局數']]:id==='dino'?[['score','單局最高分'],['played','完成局數']]:id==='summon'?[['ssr','抽到 SSR 張數'],['played','完成抽卡回合']]:['big2','uno','ttt','gomoku','ghost','directions','wolf','mines','2048','hide','seat'].includes(id)?[['wins','獲勝次數'],['streak','連勝局數'],['played','完成局數']]:[['played','完成次數']];
function createChallenge(game,metric,target){if(!games.some(g=>g[0]===game)||!metricsFor(game).some(m=>m[0]===metric)||!Number.isInteger(target)||target<1||target>10000)return false;if(state.challenges.filter(c=>!c.done).length>=3)return false;let label=metricsFor(game).find(m=>m[0]===metric)[1];state.challenges.push({id:Date.now().toString(36)+Math.random().toString(36).slice(2,7),game,metric,target,progress:0,done:false,name:games.find(g=>g[0]===game)[2]+' · '+label+' '+target});persist();return true}
function openChallenges(){openPanel('自訂挑戰','YOUR OWN KPI');ui(`<p>最多同時設定 3 項；從建立後開始計算，沒有期限。完成每項獎勵 30 點，可隨時取消。</p><form id="challengeForm"><div class="inputrow"><select id="targetGame" aria-label="挑戰遊戲">${games.map(g=>`<option value="${g[0]}">${g[2]}</option>`).join('')}</select><select id="targetMetric" aria-label="挑戰項目"></select></div><div class="inputrow"><input id="targetCount" type="number" min="1" max="10000" value="3" aria-label="目標數量" required><button class="primary">設定挑戰</button></div></form><div id="challengeMessage" role="status"></div><div class="challenge-list">${state.challenges.slice().reverse().map(c=>`<article class="challenge-entry"><strong>${c.done?'✅':'🎯'} ${c.name}</strong><div class="meter"><i style="width:${Math.min(100,c.progress/c.target*100)}%"></i></div><small>${Math.min(c.progress,c.target)}／${c.target} · ${c.done?'已領取 30 點':'進行中'}</small>${c.done?'':`<button class="quiet" data-cancel="${c.id}">取消</button>`}</article>`).join('')||'<p>還沒有挑戰，先給左右手訂個 KPI 吧 w</p>'}</div>`);function change(){$('#targetMetric').innerHTML=metricsFor($('#targetGame').value).map(([id,name])=>`<option value="${id}">${name}</option>`).join('')}change();$('#targetGame').onchange=change;$('#challengeForm').onsubmit=e=>{e.preventDefault();if(createChallenge($('#targetGame').value,$('#targetMetric').value,Number($('#targetCount').value))){openChallenges();toast('挑戰開始！下一局就會累積。')}else $('#challengeMessage').textContent='請輸入 1～10000 的整數；同時最多 3 項挑戰。'};$('#game').querySelectorAll('[data-cancel]').forEach(b=>b.onclick=()=>{state.challenges=state.challenges.filter(c=>c.id!==b.dataset.cancel);persist();openChallenges()})}
function shareLines(id){let r=state.records[id],g=games.find(g=>g[0]===id);if(id==='overall')return [playerTitle().name,'累積 '+state.plays+' 局 · Lv. '+playerLevel(),'朋友圖鑑 '+friendCatalog.filter(f=>state.friends[f.id]).length+'／7 種','完成挑戰 '+state.challenges.filter(c=>c.done).length+' 項'];return [g[2],...(recordSummary(id,r).split('｜')), '本次更新後完成 '+(r?.played||0)+' 局']}
function openShare(){openPanel('分享你的戰績','SOLO ARCADE / SHARE');ui(`<p>分享一張戰績卡給朋友。圖片只含這裡顯示的遊戲紀錄，不含聊天內容。</p><div class="choices"><select id="shareGame" aria-label="分享戰績種類"><option value="overall">我的遊樂場通行證</option>${games.map(g=>`<option value="${g[0]}">${g[2]}</option>`).join('')}</select></div><canvas id="shareCanvas" width="960" height="720" aria-label="戰績分享卡預覽"></canvas><div class="choices"><button id="shareNative" class="primary">分享圖片</button><button id="shareDownload">下載圖片</button><button id="shareLink">複製戰績與連結</button></div><p id="shareStatus" role="status"></p>`);function draw(){let ctx=$('#shareCanvas').getContext('2d');ctx.fillStyle='#171923';ctx.fillRect(0,0,960,720);ctx.fillStyle='#dfff87';ctx.fillRect(0,0,960,12);ctx.font='bold 45px sans-serif';ctx.fillText('邊緣人大全',60,100);ctx.fillStyle='#aeb0c1';ctx.font='22px sans-serif';ctx.fillText('SOLO ARCADE · PLAYER 01',60,145);let lines=shareLines($('#shareGame').value);ctx.fillStyle='#dfff87';ctx.font='bold 40px sans-serif';ctx.fillText(lines[0],60,245);ctx.fillStyle='white';ctx.font='27px sans-serif';let y=320;for(let line of lines.slice(1)){let parts=[],part='';for(let char of line){if(ctx.measureText(part+char).width>840&&part){parts.push(part);part=char}else part+=char}if(part)parts.push(part);parts.forEach(t=>{ctx.fillText(t,60,y);y+=48})}ctx.fillStyle='#aeb0c1';ctx.font='20px sans-serif';ctx.fillText('一個人，也能開桌。',60,625);ctx.fillText('fringe-arcade.sunny-haru.chatgpt.site',60,665)}draw();$('#shareGame').onchange=draw;const blob=()=>new Promise(resolve=>$('#shareCanvas').toBlob(resolve,'image/png'));function download(b){let url=URL.createObjectURL(b),a=document.createElement('a');a.href=url;a.download='solo-arcade-record.png';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}$('#shareDownload').onclick=async()=>{let b=await blob();if(b){download(b);$('#shareStatus').textContent='圖片已下載，可以貼到 LINE 或限動。'}};$('#shareNative').onclick=async()=>{let b=await blob();if(!b)return;let file=new File([b],'solo-arcade-record.png',{type:'image/png'});try{if(navigator.canShare?.({files:[file]}))await navigator.share({files:[file],title:'邊緣人大全'});else{download(b);$('#shareStatus').textContent='這個瀏覽器不支援圖片分享，已改為下載。'}}catch(e){$('#shareStatus').textContent=e.name==='AbortError'?'已取消分享。':'分享沒有成功，請使用下載圖片。'}};$('#shareLink').onclick=async()=>{let text=shareLines($('#shareGame').value).join('\n')+'\nhttps://fringe-arcade.sunny-haru.chatgpt.site';try{await navigator.clipboard.writeText(text);$('#shareStatus').textContent='已複製戰績與網址！'}catch{$('#shareStatus').textContent=text}}}
function openNPCs(){openPanel('這桌的 NPC','MEET THE TABLE');ui('<p>對手會依個性選牌，難度仍由大老二的等級設定控制。</p>'+npcProfiles.map(p=>`<article class="record-entry"><h3>${p.icon} ${p.name} · ${p.style}</h3><p>${p.desc}</p><div class="bubble">${p.win}</div></article>`).join(''))}
$('#records').onclick=openRecords;$('#friends').onclick=openFriends;$('#challenges').onclick=openChallenges;$('#shareRecord').onclick=openShare;$('#npcs').onclick=openNPCs;

// Optional support: only the payment link is public, never a bank-account fallback.
const coffeePayment={url:'',expires:0};
function coffeeMarkup(){return `<p>如果玩得開心，歡迎請我喝杯咖啡 ☕</p>${Date.now()<coffeePayment.expires?`<a class="coffee-link" href="${coffeePayment.url}" target="_blank" rel="noopener noreferrer">☕ 請作者喝咖啡 NT$60 ↗</a><small>台灣行動支付 · 請在付款頁確認或輸入 NT$60<br>連結有效至 10/8 03:20（台灣時間）</small>`:'<small>收款連結更新中，謝謝你的心意 ☕</small>'}<small>自由支持，所有遊戲都可以免費繼續玩。</small>`}
function refreshCoffee(){const home=$('#coffeeHome');if(home)home.innerHTML=coffeeMarkup();const end=$('#coffeeResult');if(end)end.innerHTML=coffeeMarkup()}
function showCoffeeResult(){let box=$('#coffeeResult');if(!box){box=document.createElement('aside');box.id='coffeeResult';box.className='coffee-support coffee-result';$('#game').appendChild(box)}box.innerHTML=coffeeMarkup()}
refreshCoffee();
document.addEventListener('click',e=>{const link=e.target.closest?.('.coffee-link');if(link&&Date.now()>=coffeePayment.expires){e.preventDefault();refreshCoffee();toast('收款連結更新中，謝謝你的心意 ☕')}});
document.addEventListener('visibilitychange',()=>{if(!document.hidden)refreshCoffee()});
